/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Mul, Pow, Rational, Sum, Sym, add, finiteDiff, finiteDiffKauers, fn, mul, pi, pow, symbols } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.series.kauers", () => {
  it("finite_diff(x**2, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(finiteDiff(pow(x, Rational.of(2n, 1n, { gcd: 1n })), x))).toBe('2*x + 1');
  });
  it("finite_diff(y**3 + 2*y**2 + 3*y + 4, y)", () => {
    const y = new Sym('y');
    expect(sympyStr(finiteDiff(add(Rational.of(4n, 1n, { gcd: 1n }), pow(y, Rational.of(3n, 1n, { gcd: 1n })), mul(Rational.of(2n, 1n, { gcd: 1n }), pow(y, Rational.of(2n, 1n, { gcd: 1n }))), mul(Rational.of(3n, 1n, { gcd: 1n }), y)), y))).toBe('3*y**2 + 7*y + 6');
  });
  it("finite_diff(x**2 + 3*x + 8, x, 2)", () => {
    const x = new Sym('x');
    expect(sympyStr(finiteDiff(add(Rational.of(8n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })), mul(Rational.of(3n, 1n, { gcd: 1n }), x)), x, Rational.of(2n, 1n, { gcd: 1n })))).toBe('4*x + 10');
  });
  it("finite_diff(z**3 + 8*z, z, 3)", () => {
    const z = new Sym('z');
    expect(sympyStr(finiteDiff(add(pow(z, Rational.of(3n, 1n, { gcd: 1n })), mul(Rational.of(8n, 1n, { gcd: 1n }), z)), z, Rational.of(3n, 1n, { gcd: 1n })))).toBe('9*z**2 + 27*z + 51');
  });
  it("finite_diff_kauers(Sum(k, (k, 1, n)))", () => {
    const [k, n] = symbols('k n');
    expect(sympyStr(finiteDiffKauers(Sum(k, [k, Rational.of(1n, 1n, { gcd: 1n }), n])))).toBe('n + 1');
  });
  it("finite_diff_kauers(Sum(1/k, (k, 1, n)))", () => {
    const [k, n] = symbols('k n');
    expect(sympyStr(finiteDiffKauers(Sum(pow(k, Rational.of(-1n, 1n, { gcd: 1n })), [k, Rational.of(1n, 1n, { gcd: 1n }), n])))).toBe('1/(n + 1)');
  });
  it("finite_diff_kauers(Sum((x*y**2), (x, 1, n), (y, 1, m)))", () => {
    const [x, y, n, m] = symbols('x y n m');
    expect(sympyStr(finiteDiffKauers(Sum(mul(x, pow(y, Rational.of(2n, 1n, { gcd: 1n }))), [x, Rational.of(1n, 1n, { gcd: 1n }), n], [y, Rational.of(1n, 1n, { gcd: 1n }), m])))).toBe('(m + 1)**2*(n + 1)');
  });
  it("finite_diff_kauers(Sum((x*y), (x, 1, m), (y, 1, n)))", () => {
    const [x, y, m, n] = symbols('x y m n');
    expect(sympyStr(finiteDiffKauers(Sum(mul(x, y), [x, Rational.of(1n, 1n, { gcd: 1n }), m], [y, Rational.of(1n, 1n, { gcd: 1n }), n])))).toBe('(m + 1)*(n + 1)');
  });
});

describe("sympy/series/tests/test_kauers.py", () => {
  it("test_finite_diff:10", () => {
    const x = new Sym('x');
    expect(sympyStr(finiteDiff(new Add([Rational.of(1n, 1n, { gcd: 1n }), new Pow(x, Rational.of(2n, 1n, { gcd: 1n })), new Mul([Rational.of(2n, 1n, { gcd: 1n }), x])]), x))).toBe('2*x + 3');
  });
  it("test_finite_diff:11", () => {
    const y = new Sym('y');
    expect(sympyStr(finiteDiff(new Add([Rational.of(5n, 1n, { gcd: 1n }), new Pow(y, Rational.of(3n, 1n, { gcd: 1n })), new Mul([Rational.of(2n, 1n, { gcd: 1n }), new Pow(y, Rational.of(2n, 1n, { gcd: 1n }))]), new Mul([Rational.of(3n, 1n, { gcd: 1n }), y])]), y))).toBe('3*y**2 + 7*y + 6');
  });
  it("test_finite_diff:12", () => {
    const z = new Sym('z');
    expect(sympyStr(finiteDiff(new Add([Rational.of(3n, 1n, { gcd: 1n }), new Pow(z, Rational.of(2n, 1n, { gcd: 1n })), new Mul([Rational.of(-2n, 1n, { gcd: 1n }), z])]), z))).toBe('2*z - 1');
  });
  it("test_finite_diff:13", () => {
    const w = new Sym('w');
    expect(sympyStr(finiteDiff(new Add([Rational.of(-2n, 1n, { gcd: 1n }), new Pow(w, Rational.of(2n, 1n, { gcd: 1n })), new Mul([Rational.of(3n, 1n, { gcd: 1n }), w])]), w))).toBe('2*w + 4');
  });
  it("test_finite_diff:14", () => {
    const x = new Sym('x');
    expect(sympyStr(finiteDiff(fn('sin', [x], { evaluate: false }), x, new Mul([Rational.of(1n, 6n, { gcd: 1n }), pi])))).toBe('-sin(x) + sin(x + pi/6)');
  });
  it("test_finite_diff:15", () => {
    const y = new Sym('y');
    expect(sympyStr(finiteDiff(fn('cos', [y], { evaluate: false }), y, new Mul([Rational.of(1n, 3n, { gcd: 1n }), pi])))).toBe('-cos(y) + cos(y + pi/3)');
  });
  it("test_finite_diff:16", () => {
    const x = new Sym('x');
    expect(sympyStr(finiteDiff(new Add([Rational.of(3n, 1n, { gcd: 1n }), new Pow(x, Rational.of(2n, 1n, { gcd: 1n })), new Mul([Rational.of(-2n, 1n, { gcd: 1n }), x])]), x, Rational.of(2n, 1n, { gcd: 1n })))).toBe('4*x');
  });
  it("test_finite_diff:17", () => {
    const n = new Sym('n');
    expect(sympyStr(finiteDiff(new Add([Rational.of(3n, 1n, { gcd: 1n }), new Pow(n, Rational.of(2n, 1n, { gcd: 1n })), new Mul([Rational.of(-2n, 1n, { gcd: 1n }), n])]), n, Rational.of(3n, 1n, { gcd: 1n })))).toBe('6*n + 3');
  });
  it("test_finite_diff_kauers:20", () => {
    const [x, n] = symbols('x n');
    expect(sympyStr(finiteDiffKauers(Sum(new Pow(x, Rational.of(2n, 1n, { gcd: 1n })), [x, Rational.of(1n, 1n, { gcd: 1n }), n])))).toBe('(n + 1)**2');
  });
  it("test_finite_diff_kauers:21", () => {
    const [y, m] = symbols('y m');
    expect(sympyStr(finiteDiffKauers(Sum(y, [y, Rational.of(1n, 1n, { gcd: 1n }), m])))).toBe('m + 1');
  });
  it("test_finite_diff_kauers:22", () => {
    const [x, y, m, n] = symbols('x y m n');
    expect(sympyStr(finiteDiffKauers(Sum(new Mul([x, y]), [x, Rational.of(1n, 1n, { gcd: 1n }), m], [y, Rational.of(1n, 1n, { gcd: 1n }), n])))).toBe('(m + 1)*(n + 1)');
  });
  it("test_finite_diff_kauers:23", () => {
    const [x, y, m, n] = symbols('x y m n');
    expect(sympyStr(finiteDiffKauers(Sum(new Mul([x, new Pow(y, Rational.of(2n, 1n, { gcd: 1n }))]), [x, Rational.of(1n, 1n, { gcd: 1n }), m], [y, Rational.of(1n, 1n, { gcd: 1n }), n])))).toBe('(m + 1)*(n + 1)**2');
  });
});
